		"viz_why_splunk": {
			"options": {
				"backgroundColor": "rgba(5, 80, 115, 0.06)",
				"fontColor": "#005073",
				"fontSize": "small",
				"markdown": "### Why Splunk when Cisco Spaces already has beautiful maps?\n\n**Cisco Spaces** shows live floor plans, room occupancy, and Detect & Locate for a single MAC. **Splunk** answers the cross-domain question David cares about: *of all the devices on the network, which ones are authenticated corporate users, which are guests, and which should we investigate?* — with **building and floor context**, over **your chosen time range**, next to firewall, DNAC, and identity data.\n\n> *Spaces tells you where they are. Splunk tells you which devices on the network are trusted.*"
			},
			"type": "splunk.markdown"
		}
	},
	"dataSources": {
		"ds_annotation_occupancy_spike": {
			"name": "Occupancy spikes",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" | rename spaceOccupancy.peakPeopleCount as people, spaceOccupancy.space.capacity as capacity, spaceOccupancy.space.name as room | where isnotnull(capacity) AND capacity>0 AND isnotnull(people) AND people>0 | eval pct=round(people/capacity*100, 0) | where pct > 50 | eval label=room.\" — \".pct.\"% full\" | table _time label",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_building_occupancy": {
			"name": "KPI Rooms Occupied",
			"options": {
				"extend": "ds_occupancy_trend",
				"query": "| fields _time \"Rooms Occupied\""
			},
			"type": "ds.chain"
		},
		"ds_device_by_building": {
			"name": "Devices by Building",
			"options": {
				"extend": "ds_location_breakdown",
				"query": "| stats sum(\"Unique Devices\") as \"Unique Devices\" by Building"
			},
			"type": "ds.chain"
		},
		"ds_device_presence_trend": {
			"name": "Device Presence Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\" devicePresence.location.inferredLocationTypes{}=FLOOR | eval active='devicePresence.activeDevicesCount', floor='devicePresence.location.name', city='devicePresence.location.parent.parent.name' | bin _time span=15m | stats max(active) as active by _time, floor, city | timechart span=15m fixedrange=false sum(active) by city",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_devices_trend": {
			"name": "Connected Devices Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_LOCATION_UPDATE\" | timechart fixedrange=false dc('deviceLocationUpdate.device.macAddress') as \"Connected Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_devices": {
			"name": "KPI Connected Devices",
			"options": {
				"extend": "ds_devices_trend",
				"query": "| fields _time \"Connected Devices\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_ssids": {
			"name": "KPI Active SSIDs",
			"options": {
				"extend": "ds_ssids_trend",
				"query": "| fields _time \"Active SSIDs\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_users": {
			"name": "Active Users",
			"options": {
				"extend": "ds_user_presence_total",
				"query": "| fields _time \"Active Users\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_webex_count": {
			"name": "KPI Webex Devices",
			"options": {
				"extend": "ds_webex_trend",
				"query": "| fields _time \"Webex Devices\""
			},
			"type": "ds.chain"
		},
		"ds_location_breakdown": {
			"name": "Building Resilience - Spaces Location Breakdown",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_LOCATION_UPDATE\" \n| stats dc('deviceLocationUpdate.device.macAddress') as \"Unique Devices\", latest(deviceLocationUpdate.location.apCount) as \"AP Count\" by deviceLocationUpdate.location.parent.parent.name, deviceLocationUpdate.location.parent.name, deviceLocationUpdate.location.name \n| rename deviceLocationUpdate.location.parent.parent.name as Campus, deviceLocationUpdate.location.parent.name as Building, deviceLocationUpdate.location.name as Floor",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_occupancy_trend": {
			"name": "Rooms Occupied Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" \"spaceOccupancy.space.type\"=ROOM | bin _time span=15m | stats max(spaceOccupancy.space.capacity) as capacity, max(spaceOccupancy.peakPeopleCount) as peakPeopleCount, latest(spaceOccupancy.peoplePresence) as peoplePresence by _time, spaceOccupancy.space.floorId, spaceOccupancy.space.name | eval occupied=if(peoplePresence==\"true\" OR peakPeopleCount>0, 1, 0) | stats dc(spaceOccupancy.space.name) as total_rooms, sum(occupied) as rooms_occupied by _time | eval score=if(total_rooms>0, round(rooms_occupied/total_rooms*100, 2), 0) | timechart span=15m fixedrange=false max(score) as \"Rooms Occupied\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_detail": {
			"name": "Building Resilience - Room Detail",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\"\n| stats latest(spaceOccupancy.peoplePresence) as Presence, latest(spaceOccupancy.peakPeopleCount) as \"Peak Count\", latest(spaceOccupancy.space.capacity) as Capacity, latest(spaceOccupancy.bookingStatus) as Booked, latest(spaceOccupancy.location.name) as Floor, latest(spaceOccupancy.location.parent.name) as Building by spaceOccupancy.space.name\n| rename spaceOccupancy.space.name as Room\n| eval Presence=if(Presence==\"true\", \"Occupied\", \"Empty\"), Booked=if(Booked==\"true\", \"Yes\", \"No\"), \"Utilization %\"=if(Capacity>0, round('Peak Count'/Capacity*100, 2), 0)\n| sort Building, Floor, Room",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_rooms": {
			"name": "Room Utilization by Building",
			"options": {
				"extend": "ds_room_detail",
				"query": "| eval occupied=if(Presence=\"Occupied\", 1, 0) \n| stats count as rooms_total, sum(occupied) as rooms_used by Building | rename rooms_total as \"Total Rooms\", rooms_used as \"Rooms Used\""
			},
			"type": "ds.chain"
		},
		"ds_ssid_clients": {
			"name": "Building Resilience - SSID Clients",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\"\n| eval ssid='deviceAssociation.ssid', event='deviceAssociation.event', building=coalesce('deviceAssociation.location.parent.parent.name', 'deviceAssociation.location.parent.name', 'deviceAssociation.location.name')\n| search event=\"ASSOCIATE\"\n| stats dc(deviceAssociation.device.macAddress) as Clients by ssid\n| sort -Clients\n| rename ssid as SSID",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ssid_trend": {
			"name": "SSID Client Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\" | eval ssid='deviceAssociation.ssid' | timechart fixedrange=false dc(deviceAssociation.device.macAddress) as clients by ssid",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ssids_trend": {
			"name": "Active SSIDs Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" | eval ssid='deviceAssociation.ssid', event='deviceAssociation.event' | search event=\"ASSOCIATE\" | timechart fixedrange=false dc(ssid) as \"Active SSIDs\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_user_presence_total": {
			"name": "User Presence Total",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"USER_PRESENCE\" | timechart fixedrange=false max(userPresence.activeUsersCount.totalUsers) as \"Active Users\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_user_presence_trend": {
			"name": "Building Resilience - User Presence Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\"\n| `spaces_hierarchy(deviceCounts)`\n| eval users=tonumber(mvindex('deviceCounts.userCount', 0)), city=coalesce(campus, building, site)\n| where isnotnull(users) AND isnotnull(floor) AND isnotnull(city) AND city!=\"Unknown\"\n| bin _time span=15m\n| stats max(users) as users by _time, floor, city\n| stats sum(users) as users by _time, city\n| timechart span=15m fixedrange=false sum(users) by city",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_webex_by_building": {
			"name": "Webex Devices by Building",
			"options": {
				"extend": "ds_webex_devices",
				"query": "| stats count by Building"
			},
			"type": "ds.chain"
		},
		"ds_webex_devices": {
			"name": "Building Resilience - Webex Devices",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| stats latest(webexTelemetryUpdate.deviceInfo.displayName) as Device, latest(webexTelemetryUpdate.deviceInfo.product) as Product, latest(webexTelemetryUpdate.deviceInfo.ipAddress) as IP, latest(webexTelemetryUpdate.deviceInfo.softwareVersion) as Firmware, latest(webexTelemetryUpdate.location.name) as Building, latest(webexTelemetryUpdate.location.parent.name) as Campus by webexTelemetryUpdate.deviceInfo.serialNumber\n| rename webexTelemetryUpdate.deviceInfo.serialNumber as Serial\n| sort Device",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_webex_people_trend": {
			"name": "Webex People Count Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\" | eval people='webexTelemetryUpdate.telemetries{}.peopleCount', device='webexTelemetryUpdate.deviceInfo.serialNumber', location=coalesce('webexTelemetryUpdate.location.parent.name', 'webexTelemetryUpdate.location.name') | where isnotnull(people) AND people >= 0 AND isnotnull(location) | bin _time span=15m | stats max(people) as people by _time, device, location | timechart span=15m fixedrange=false sum(people) as \"People Detected\" by location",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_webex_trend": {
			"name": "Webex Devices Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\" | timechart fixedrange=false dc(webexTelemetryUpdate.deviceInfo.serialNumber) as \"Webex Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_trust_review": {
			"name": "Building Resilience - Wireless Devices To Review",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" (eventType=\"DEVICE_LOCATION_UPDATE\" OR (eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"))\n| eval mac=lower(replace(coalesce('deviceLocationUpdate.device.macAddress', 'deviceAssociation.device.macAddress'), \":\", \"-\"))\n| where isnotnull(mac) AND mac!=\"\"\n| eval ssid=coalesce('deviceAssociation.ssid', \"\")\n| eval spaces_user_id=coalesce('deviceLocationUpdate.device.userId', \"\")\n| eval building=coalesce('deviceLocationUpdate.location.parent.name', 'deviceAssociation.location.parent.name', 'deviceAssociation.location.parent.parent.name')\n| eval floor=coalesce('deviceLocationUpdate.location.name', 'deviceAssociation.location.name')\n| eval spaces_type=coalesce('deviceLocationUpdate.device.type', \"\")\n| stats latest(spaces_user_id) as spaces_user_id, latest(building) as building, latest(floor) as floor, latest(spaces_type) as spaces_type, values(ssid) as ssid_mv by mac\n| eval ssid=coalesce(mvindex(ssid_mv, 0), \"\")\n| fields - ssid_mv\n| join mac type=left [\n    search `index_identity` sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5400\")\n    | eval mac=lower(replace(coalesce(Calling_Station_ID, EndPointMACAddress), \":\", \"-\"))\n    | where isnotnull(mac) AND len(mac)>=11\n    | eval identity=lower(trim(coalesce(user, user_name, User_Name, 'User-Name', username, \"\")))\n    | where NOT match(identity, \"^#ctsrequest#$\") AND NOT match(identity, \"^#[^#]+#$\")\n    | eval ise_pass=if(match(_raw, \"5200\") OR match(_raw, \"(?i)CISE_Passed\"), 1, 0)\n    | stats latest(identity) as ise_user, max(ise_pass) as ise_pass, latest(EndpointIdentityGroup) as ise_profile by mac\n  ]\n| eval guest_ssid=if(match(ssid, \"(?i)guest\"), 1, 0)\n| eval corp_ssid=if(isnotnull(ssid) AND ssid!=\"\" AND guest_ssid=0, 1, 0)\n| eval segment=case(\n    ise_pass=1 AND guest_ssid=0, \"Corporate authenticated\",\n    ise_pass=1 AND guest_ssid=1, \"Guest authenticated\",\n    guest_ssid=1, \"Guest WLAN only\",\n    isnotnull(spaces_user_id) AND spaces_user_id!=\"\", \"Spaces-identified device\",\n    isnull(ise_user) OR ise_user=\"\", \"No ISE identity\",\n    1==1, \"Other — review\"\n  )\n| eval ise_result=case(ise_pass=1, \"Pass\", isnotnull(ise_user) AND ise_user!=\"\", \"Fail/No pass in window\", 1==1, \"No ISE record\")\n| eval why_flagged=case(\n    corp_ssid=1 AND ise_result=\"No ISE record\", \"On corporate SSID but no ISE authentication in this window\",\n    corp_ssid=1 AND ise_result=\"Fail/No pass in window\", \"Corporate SSID — ISE did not record a pass in this window\",\n    guest_ssid=1 AND ise_result=\"No ISE record\", \"Guest SSID with no ISE guest auth in this window\",\n    segment=\"No ISE identity\", \"Spaces sees device; ISE has no user identity for this MAC\",\n    segment=\"Other — review\", \"Unclassified — validate in Spaces Detect & Locate\",\n    1==1, segment\n  )\n| where NOT (ise_pass=1 AND guest_ssid=0)\n| eval Building=coalesce(building, \"Unknown\"), Floor=coalesce(floor, \"\"), \"ISE User\"=coalesce(ise_user, \"\"), \"ISE Profile\"=coalesce(ise_profile, \"\"), \"Spaces Type\"=coalesce(spaces_type, \"\")\n| table mac Building Floor SSID \"ISE User\" \"ISE Profile\" ise_result \"Spaces Type\" segment why_flagged\n| rename mac as MAC, ise_result as \"ISE Result\", why_flagged as \"Why Flagged\", segment as Segment\n| sort Building, SSID, -\"ISE Result\"\n| head 200",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_trust_review_count": {
			"name": "Devices To Review KPI",
			"options": {
				"extend": "ds_trust_review",
				"query": "| stats dc(MAC) as count"
			},
			"type": "ds.chain"
		},
		"ds_trust_summary": {
			"name": "Building Resilience - Wireless Device Trust Summary",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" (eventType=\"DEVICE_LOCATION_UPDATE\" OR (eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"))\n| eval mac=lower(replace(coalesce('deviceLocationUpdate.device.macAddress', 'deviceAssociation.device.macAddress'), \":\", \"-\"))\n| where isnotnull(mac) AND mac!=\"\"\n| eval ssid=coalesce('deviceAssociation.ssid', \"\")\n| eval spaces_user_id=coalesce('deviceLocationUpdate.device.userId', \"\")\n| stats latest(spaces_user_id) as spaces_user_id, values(ssid) as ssid_mv by mac\n| eval ssid=coalesce(mvindex(ssid_mv, 0), \"\")\n| fields - ssid_mv\n| join mac type=left [\n    search `index_identity` sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5400\")\n    | eval mac=lower(replace(coalesce(Calling_Station_ID, EndPointMACAddress), \":\", \"-\"))\n    | where isnotnull(mac) AND len(mac)>=11\n    | eval identity=lower(trim(coalesce(user, user_name, User_Name, 'User-Name', username, \"\")))\n    | where NOT match(identity, \"^#ctsrequest#$\") AND NOT match(identity, \"^#[^#]+#$\")\n    | eval ise_pass=if(match(_raw, \"5200\") OR match(_raw, \"(?i)CISE_Passed\"), 1, 0)\n    | stats latest(identity) as ise_user, max(ise_pass) as ise_pass by mac\n  ]\n| eval guest_ssid=if(match(ssid, \"(?i)guest\"), 1, 0)\n| eval segment=case(\n    ise_pass=1 AND guest_ssid=0, \"Corporate authenticated\",\n    ise_pass=1 AND guest_ssid=1, \"Guest authenticated\",\n    guest_ssid=1, \"Guest WLAN only\",\n    isnotnull(spaces_user_id) AND spaces_user_id!=\"\", \"Spaces-identified device\",\n    isnull(ise_user) OR ise_user=\"\", \"No ISE identity\",\n    1==1, \"Other — review\"\n  )\n| stats dc(mac) as Devices by segment\n| rename segment as Segment\n| sort -Devices",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
